import{_ as d,o as e,c as o,a5 as s}from"./chunks/framework.CQwNn0Y-.js";const g=JSON.parse('{"title":"插件","description":"","frontmatter":{},"headers":[],"relativePath":"guide/plugins.md","filePath":"guide/plugins.md","lastUpdated":1792245757000}'),a={name:"guide/plugins.md"};function i(r,t,n,l,h,c){return e(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to “插件”">​</a></h1><h2 id="插件是什么" tabindex="-1">插件是什么 <a class="header-anchor" href="#插件是什么" aria-label="Permalink to “插件是什么”">​</a></h2><p><strong>插件是 <code>ZenFile.exe --plugin &lt;id&gt;</code> 启动的独立进程。</strong></p><p>不是独立 exe，不是 DLL，也不 hook 宿主内存：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ZenFile.exe                     ← 宿主：窗口、托盘、文件操作、插件生命周期</span></span>
<span class="line"><span>└── ZenFile.exe --plugin &lt;id&gt;   ← 插件：独立进程，崩了不影响宿主</span></span></code></pre></div><h2 id="为什么要这样设计" tabindex="-1">为什么要这样设计 <a class="header-anchor" href="#为什么要这样设计" aria-label="Permalink to “为什么要这样设计”">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>做法</th><th>原因</th></tr></thead><tbody><tr><td>插件崩了不能带崩宿主</td><td>每个插件一个<strong>进程</strong></td><td>进程间无共享地址空间，panic / 越界 / 死循环都碰不到宿主</td></tr><tr><td>不要一堆 exe 要单独升级</td><td>同一个 exe + <code>--plugin &lt;id&gt;</code></td><td>升级一次到位，协议版本永远一致</td></tr><tr><td>宿主退了不能留孤儿</td><td>全部挂进同一个 <strong>Job Object</strong></td><td><code>JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE</code>，句柄一关内核自动终结全部子进程</td></tr><tr><td>插件卡死也要能发现</td><td><strong>心跳 + 超时</strong>（5 秒）</td><td>进程还活着不代表有用——死循环、弹了个模态框都算卡死</td></tr><tr><td>插件别跑在 Job 之外</td><td><code>CREATE_SUSPENDED</code> → 入 Job → <code>ResumeThread</code></td><td>拉起即入组，杜绝「已跑起来才入组失败」的窗口期</td></tr></tbody></table><p>明确<strong>不提供</strong>：hook 宿主内存、装 API hook、读宿主函数表。 想要新功能就改宿主代码重新编译，而不是塞一段机器码进去。</p><h2 id="安装一个插件" tabindex="-1">安装一个插件 <a class="header-anchor" href="#安装一个插件" aria-label="Permalink to “安装一个插件”">​</a></h2><p>在 <code>ZenFile.exe</code> <strong>同级</strong>建 <code>plugins/&lt;插件 id&gt;/</code> 目录，往里放一份 <code>plugin.json</code>：</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;hello-demo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你好插件&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;第一个插件&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;protocol_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;autostart&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;capabilities&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;core.log&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>插件不需要编译任何代码</strong>——因为插件就是 ZenFile 自己的另一个进程。 重启 ZenFile，打开「设置 - 插件」，面板上就能看到它。</p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td>✓</td><td>唯一标识，<strong>只能用 <code>[a-z0-9_-]</code></strong>。会进管道名与命令行参数</td></tr><tr><td><code>name</code></td><td>✓</td><td>面板上显示的名字</td></tr><tr><td><code>description</code></td><td></td><td>一行说明，显示在名字下面</td></tr><tr><td><code>protocol_version</code></td><td></td><td>填 <code>0</code> 或省略 = 不校验。填了且 ≠ 1 则拒绝拉起</td></tr><tr><td><code>autostart</code></td><td></td><td><code>true</code> = 宿主启动时自动拉起</td></tr><tr><td><code>capabilities</code></td><td></td><td>申请的能力。<strong>没申请的调用宿主直接拒</strong></td></tr></tbody></table><p><code>plugin.json</code> 必须 UTF-8 <strong>无 BOM</strong>，且放在插件子目录里，不能写在 <code>plugins/</code> 根下。</p><h2 id="面板状态" tabindex="-1">面板状态 <a class="header-anchor" href="#面板状态" aria-label="Permalink to “面板状态”">​</a></h2><p>「设置 - 插件」里六种状态（<code>PluginState::as_str()</code>）：</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td>已禁用</td><td>你关掉了它</td></tr><tr><td>启动中</td><td>进程已拉起，还没握手</td></tr><tr><td>运行中</td><td>正常</td></tr><tr><td>已停止</td><td>进程没了，正在等重启</td></tr><tr><td>无响应</td><td>心跳超时，会被杀掉重启</td></tr><tr><td>启动失败</td><td>连续崩溃到上限，或清单 / 协议有问题</td></tr></tbody></table><h2 id="崩溃隔离" tabindex="-1">崩溃隔离 <a class="header-anchor" href="#崩溃隔离" aria-label="Permalink to “崩溃隔离”">​</a></h2><p>宿主在 100ms 定时器里检查两件事，<strong>顺序不能反</strong>：</p><ol><li>先判<strong>进程还在不在</strong>，再判心跳。崩掉的插件 pid 还在句柄表里但已不存活， 先判心跳会把「已崩溃」误记成「无响应」，排查方向都被带偏。</li><li>进程没了 → 崩溃计数 +1 → 连续 4 次后<strong>停止重启</strong>（<code>MAX_RESTARTS = 3</code>）。</li></ol><p>上限是必须的：一个一启动就崩的插件无限重启，会变成「任务管理器里 ZenFile 疯狂拉进程」 的灾难，比崩溃本身更糟。</p><h2 id="可申请的能力" tabindex="-1">可申请的能力 <a class="header-anchor" href="#可申请的能力" aria-label="Permalink to “可申请的能力”">​</a></h2><table tabindex="0"><thead><tr><th>字符串</th><th>含义</th></tr></thead><tbody><tr><td><code>clipboard.history</code></td><td>读剪贴板历史</td></tr><tr><td><code>screenshot.capture</code></td><td>触发截图</td></tr><tr><td><code>taskmgr.snapshot</code></td><td>拉取进程 / 性能快照</td></tr><tr><td><code>terminal.open</code></td><td>在当前目录开终端</td></tr><tr><td><code>preview.open</code></td><td>请求预览文件</td></tr><tr><td><code>core.log</code></td><td>写一行日志</td></tr></tbody></table><p>能力名<strong>点号小写与 PascalCase 两种写法都收</strong>（<code>clipboard.history</code> 与 <code>ClipboardHistory</code> 等价）。写错时报错会列出全部可用名字。</p><div class="warning custom-block"><p class="custom-block-title">当前限制</p><p><strong>能力调用链路（<code>call</code> / <code>result</code>）尚未实现。</strong> 宿主侧读线程目前只认 <code>hello</code> 和 <code>beat</code>。 当前可验收的范围是：装得上、看得见、进程能拉起、能握手、能持续心跳、崩了能兜住。</p></div><h2 id="排查" tabindex="-1">排查 <a class="header-anchor" href="#排查" aria-label="Permalink to “排查”">​</a></h2><p>宿主把插件现状写进 <code>%TEMP%\\zenfile_plugins.log</code>：</p><table tabindex="0"><thead><tr><th>前缀</th><th>时机</th><th>内容</th></tr></thead><tbody><tr><td><code>[discover]</code></td><td>扫描目录时</td><td>每个插件的 id / name / state / pid / crashes / error</td></tr><tr><td><code>[beat]</code></td><td>心跳变化时（节流后约 2.5 s 一行）</td><td>心跳时刻、age、greeted、管道名</td></tr></tbody></table><p><strong>判「管道通没通」只能看 <code>[beat]</code> 行的 <code>last_beat</code> 是否在变</strong>， 不能靠「没看到失败日志」反推——那不叫验证，那叫没测。</p><p>Windows subsystem 下 <code>eprintln!</code> / stderr 拿不到，写文件是唯一可靠手段。</p><h3 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h3><p><strong>面板显示「没有找到插件」</strong><code>plugins/</code> 目录要和 <code>ZenFile.exe</code> 放在一起，不是 exe 的工作目录。</p><p><strong>面板显示「启动失败 · 读不到 plugin.json」</strong> 清单路径不对或 JSON 语法错误。必须在插件子目录里，且为 UTF-8 无 BOM。</p><p><strong>面板显示「协议版本不兼容」</strong><code>protocol_version</code> 与宿主对不上。宿主当前是 <code>1</code>，填 <code>0</code> 可跳过校验。</p><p><strong>面板卡在「启动中」，<code>greeted=false</code></strong> 管道建了但没通。查 <code>[beat]</code> 行的 <code>age_ms</code> 是否持续增长——增长就是没收到心跳。</p><p><strong>面板反复「已停止」→「启动失败」</strong> 插件进程起来就退。手动跑一次看退出码：<code>3</code> = 管道连不上，<code>2</code> = id 非法。</p><h2 id="想自己写一个" tabindex="-1">想自己写一个？ <a class="header-anchor" href="#想自己写一个" aria-label="Permalink to “想自己写一个？”">​</a></h2><p>看 <a href="/zenfile/docs/new-plugin.html">开始你的第一个插件</a>，那是照着能做完的操作路径。</p><h2 id="协议" tabindex="-1">协议 <a class="header-anchor" href="#协议" aria-label="Permalink to “协议”">​</a></h2><p>传输是<strong>换行（<code>\\n</code>）分隔的 JSON</strong>，一行一条消息，经由命名管道 <code>\\\\.\\pipe\\ZenFile.{pid}.{safe_id}</code> 传输。</p><table tabindex="0"><thead><tr><th><code>t</code></th><th>方向</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>hello</code></td><td>插件 → 宿主</td><td><code>{&quot;t&quot;:&quot;hello&quot;,&quot;id&quot;:...,&quot;protocol&quot;:1,&quot;argv&quot;:[...]}</code></td><td>握手</td></tr><tr><td><code>beat</code></td><td>插件 → 宿主</td><td><code>{&quot;t&quot;:&quot;beat&quot;}</code></td><td>心跳，间隔取超时的一半（2500 ms）</td></tr><tr><td><code>shutdown</code></td><td>宿主 → 插件</td><td>—</td><td>收到后应干净退出，返回 <code>0</code></td></tr><tr><td><code>call</code></td><td>宿主 → 插件</td><td><code>{&quot;t&quot;:&quot;call&quot;,&quot;id&quot;:N,...}</code></td><td>一次能力调用</td></tr><tr><td><code>result</code></td><td>插件 → 宿主</td><td><code>{&quot;t&quot;:&quot;result&quot;,&quot;id&quot;:N,&quot;ok&quot;:bool,&quot;payload&quot;:...}</code></td><td>对 <code>call</code> 的响应</td></tr></tbody></table><p>三条纪律：</p><ol><li><strong>心跳必须自己主动发，不能等宿主来问。</strong> 宿主判断「插件还活着」的唯一依据就是这条。</li><li><strong>收到 <code>call</code> 必须回响应，哪怕回失败。</strong> 不回的话宿主那边挂着一个等不到的请求。</li><li><strong>读消息时半截 JSON 要留着等下一次。</strong> 管道是字节流，一次读拿到的很可能只是半条消息。</li></ol><p>完整细节见 <a href="/zenfile/docs/api.html">ZenFile API</a>。</p>`,44)])])}const k=d(a,[["render",i]]);export{g as __pageData,k as default};
